const fs=require('fs'),assert=require('node:assert/strict'),{chromium}=require('playwright');
(async()=>{const b=await chromium.launch({executablePath:'/usr/bin/chromium',args:['--no-sandbox']}),page=await b.newPage({hasTouch:true,reducedMotion:'reduce'}),errors=[],rows=[],base=process.env.ROOT+'/lol-coach/',out=process.env.OUT;page.on('pageerror',e=>errors.push(e.stack));
for(const [device,width,height]of [['desktop',1440,1000],['mobile',390,844]]){
 await page.setViewportSize({width,height});await page.goto(base+'loading.html');await page.waitForSelector('#analyze:enabled');await page.locator('#example-0').click();await page.locator('#analyze').click();const h=page.locator('#loading-coach');await h.locator('[data-action-kind=TRADE]').waitFor();const trade=await h.locator('[data-action-kind=TRADE]').innerText();assert.match(trade,/미니언을 먼저 잡는 흐름.*막타를 치러/s);assert(!trade.includes('여유를 늦추'));await h.locator('[data-action-kind=TRADE]').click();assert.match(await h.locator('[data-action-detail=lane-methods]').innerText(),/견제 때문에 미니언 잡기가 늦어지면/);
 await h.locator('[data-coach-focus=tab-fight]').click();const f=h.locator('.formation-explorer'),arena=()=>f.locator('.formation-arena').first();assert.equal(await arena().locator('[data-range-tier=DIRECT]').count(),10);assert.equal(await arena().locator('[data-range-tier=COMMITTED]').count(),7);assert.equal(await arena().locator('.formation-actor').count(),10);
 const fit=async()=>assert(await arena().locator('[data-range-champion]').evaluateAll(cs=>cs.every(c=>{const x=Number(c.getAttribute('cx')),y=Number(c.getAttribute('cy')),r=Number(c.getAttribute('r'));return x-r>=0&&y-r>=0&&x+r<=100&&y+r<=100;})),'all overview circles must fit');await fit();
 assert(await arena().evaluate(e=>{const a=e.getBoundingClientRect();return Math.abs(a.width-a.height)<2&&[...e.querySelectorAll('.formation-portrait')].every(p=>p.getBoundingClientRect().width<25);}));
 assert(await arena().evaluate(e=>[...e.querySelectorAll('[data-range-tier=DIRECT]')].every(c=>{const p=e.querySelector('[data-formation-champion='+c.dataset.rangeChampion+'] .formation-portrait').getBoundingClientRect(),r=e.getBoundingClientRect();return Math.abs(p.x+p.width/2-r.x-Number(c.getAttribute('cx'))/100*r.width)<2&&Math.abs(p.y+p.height/2-r.y-Number(c.getAttribute('cy'))/100*r.height)<2;})));
 await f.evaluate(e=>e.scrollIntoView({block:'start',behavior:'instant'}));await page.screenshot({path:out+'/'+device+'-overview.png'});await arena().screenshot({path:out+'/'+device+'-all-rings.png'});
 const picker=f.locator('.formation-roster');await picker.locator('summary').click();if(device==='mobile')await picker.locator('[data-formation-control="pick-ALLY:Sejuani"]').tap();else await picker.locator('[data-formation-control="pick-ALLY:Sejuani"]').click();assert.equal(await arena().locator('[data-range-tier=DIRECT]').count(),10);assert.match(await f.locator('.formation-threat-summary').innerText(),/빙하 감옥\(R\).*1300.*1950/s);assert(await picker.evaluate(e=>e.open));await picker.locator('[data-formation-control="pick-ALLY:Sejuani"]').focus();await page.keyboard.press('Enter');assert.equal(await page.evaluate(()=>document.activeElement?.dataset.formationControl),'pick-ALLY:Sejuani');assert.equal(await arena().locator('[data-range-champion=Caitlyn][data-range-tier=DIRECT]').evaluate(e=>getComputedStyle(e).stroke),'rgb(239, 202, 117)');const sej=await f.locator('.formation-threat-summary').innerText();await f.locator('[data-formation-control=range-SELECTED]').click();assert.equal(await arena().locator('[data-range-champion]').count(),2);await f.locator('[data-formation-control=range-ALL]').click();await f.locator('[data-formation-control=view-LAYOUT]').click();await arena().screenshot({path:out+'/'+device+'-layout.png'});await f.locator('[data-formation-control=view-OVERVIEW]').click();
 await picker.evaluate(e=>e.open=true);await picker.locator('[data-formation-control="pick-ENEMY:Zed"]').click();assert.match(await f.locator('.formation-threat-summary').innerText(),/살아있는 그림자\(W\).*죽음의 표식\(R\).*1275/s);assert.match(await f.locator('.formation-threat-summary').innerText(),/위치|그림자/);const zed=await f.locator('.formation-threat-summary').innerText();
 await f.locator('[data-formation-control=FLANK_ISOLATE]').click();await f.locator('[data-formation-control=step-1]').click();await fit();await f.evaluate(e=>e.scrollIntoView({block:'start',behavior:'instant'}));await page.screenshot({path:out+'/'+device+'-flank.png'});
 await f.locator('[data-formation-zoom]').click();const dialog=f.locator('dialog');await dialog.locator('[data-formation-control=step-2]').click();assert.equal(await arena().getAttribute('data-formation-step'),'2');await dialog.locator('[data-formation-control=range-OFF]').click();assert.equal(await arena().locator('[data-range-champion]').count(),0);await dialog.locator('[data-formation-control=range-ALL]').click();await page.keyboard.press('Escape');await page.waitForFunction(()=>document.activeElement?.hasAttribute('data-formation-zoom'));await f.locator('[data-formation-control=links]').first().focus();await page.keyboard.press('Enter');assert.equal(await arena().locator('.formation-connection').count(),0);await f.locator('[data-formation-control=links]').first().click();
 if(device==='mobile'){await page.setViewportSize({width:320,height:844});for(const tab of ['lane','operations','fight']){await h.locator('[data-coach-focus=tab-'+tab+']').tap();await page.evaluate(()=>document.documentElement.style.fontSize='200%');assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await page.evaluate(()=>document.documentElement.style.fontSize='');}await fit();await page.setViewportSize({width:390,height:844});}
 await page.locator('#input-panel').evaluate(e=>e.open=true);await page.locator('#pick-ENEMY-2').fill('Sona');assert(await page.locator('#loading-results').isHidden());await page.locator('#analyze').click();await h.locator('[data-coach-focus=tab-fight]').click();assert.equal(await arena().locator('[data-range-tier=DIRECT]').count(),10);assert.equal(await arena().locator('[data-range-champion=Sona].is-partial').count(),1);await f.locator('.formation-roster').evaluate(e=>e.open=true);await f.locator('[data-formation-control="pick-ENEMY:Sona"]').click();assert.match(await f.locator('.formation-threat-summary').innerText(),/기술 위협 범위는 미확인/);
 await page.locator('#input-panel').evaluate(e=>e.open=true);await page.locator('#pick-ENEMY-3').fill('Jinx');await page.locator('#analyze').click();await h.locator('[data-coach-focus=tab-fight]').click();assert.equal(await f.locator('.formation-arena').count(),0);
 await page.goto(base+'directions.html');await page.locator('#formation-study .formation-arena').waitFor();assert.equal(await page.locator('#formation-study [data-range-tier=DIRECT]').count(),10);assert.equal(await page.locator('.scene-card').count(),6);rows.push({device,trade,sejuani:sej,zed,primary_count:10,conditional_count:7,small_portraits:true,overview_fit:true});
}
assert.deepEqual(errors,[]);fs.writeFileSync(out+'/result.json',JSON.stringify({passed:true,rows,errors,real_coaching_n:0,observed_positions:false},null,2));await b.close();})().catch(e=>{console.error(e);process.exit(1)});
